    System.Runtime.InteropServices.Marshal.Copy(d.Scan0, px, 0, px.Length);
    // flood the near-white background from the edges
    var seen = new bool[w * h];
    var q = new Queue<int>();
    Func<int, bool> white = i => px[i * 4] > 225 && px[i * 4 + 1] > 225 && px[i * 4 + 2] > 225;
    for (int x = 0; x < w; x++) { q.Enqueue(x); q.Enqueue((h - 1) * w + x); }
    for (int y = 0; y < h; y++) { q.Enqueue(y * w); q.Enqueue(y * w + w - 1); }
    while (q.Count > 0) {
      int i = q.Dequeue();
      if (i < 0 || i >= w * h || seen[i] || !white(i)) continue;
      seen[i] = true;
      int x = i % w, y = i / w;
      if (x > 0) q.Enqueue(i - 1); if (x < w - 1) q.Enqueue(i + 1);
      if (y > 0) q.Enqueue(i - w); if (y < h - 1) q.Enqueue(i + w);
    }
    int minx = w, miny = h, maxx = 0, maxy = 0;
    for (int i = 0; i < w * h; i++) {
      if (seen[i]) { px[i * 4 + 3] = 0; continue; }
      // soften the edge: pixels next to the background fade with how white they are
      int x = i % w, y = i / w;
      bool edge = (x > 0 && seen[i - 1]) || (x < w - 1 && seen[i + 1]) || (y > 0 && seen[i - w]) || (y < h - 1 && seen[i + w]);
      if (edge) {
        int m = Math.Min(px[i * 4], Math.Min(px[i * 4 + 1], px[i * 4 + 2]));
        px[i * 4 + 3] = (byte)Math.Max(0, Math.Min(255, (255 - m) * 3));
      }
      if (x < minx) minx = x; if (x > maxx) maxx = x; if (y < miny) miny = y; if (y > maxy) maxy = y;
    }
    System.Runtime.InteropServices.Marshal.Copy(px, 0, d.Scan0, px.Length);
    bmp.UnlockBits(d);
    var crop = bmp.Clone(new Rectangle(minx, miny, maxx - minx + 1, maxy - miny + 1), PixelFormat.Format32bppArgb);
    // keep it modest in size
    int tw = 256, th = (int)Math.Round(256.0 * crop.Height / crop.Width);
    var outb = new Bitmap(tw, th, PixelFormat.Format32bppArgb);
    using (var g = Graphics.FromImage(outb)) {
      g.InterpolationMode = System.Drawing.Drawing2D.InterpolationMode.HighQualityBicubic;
      g.DrawImage(crop, 0, 0, tw, th);
    }
    outb.Save(dst, ImageFormat.Png);
    Console.WriteLine("saved " + tw + "x" + th + " from " + crop.Width + "x" + crop.Height);
  }
